- Test: `scripts/tests/research-spine-flow.test.mjs`

- [ ] **Step 1: Write failing config assertions inside the research flow test**

Add imports near the top of `scripts/tests/research-spine-flow.test.mjs`:

```js
import {
  getReviewVaultRoot,
  resolveReviewPath,
} from '../lib/config.mjs';
```

Add this test after the dry-run tests:

```js
await runTest('review vault defaults to World_Machine and resolves review paths', async () => {
  const previousWorldRoot = process.env.WORLD_MACHINE_ROOT;
  const previousReviewRoot = process.env.REVIEW_VAULT_ROOT;
  const tempRoot = mkdtempSync(join(tmpdir(), 'world-machine-review-'));

  try {
    process.env.WORLD_MACHINE_ROOT = tempRoot;
    delete process.env.REVIEW_VAULT_ROOT;

    assert.equal(getReviewVaultRoot(), tempRoot);
    assert.equal(resolveReviewPath('Reports', 'Daily'), join(tempRoot, 'Reports', 'Daily'));
  } finally {
    if (previousWorldRoot === undefined) {
      delete process.env.WORLD_MACHINE_ROOT;
    } else {
      process.env.WORLD_MACHINE_ROOT = previousWorldRoot;
    }
    if (previousReviewRoot === undefined) {
      delete process.env.REVIEW_VAULT_ROOT;
    } else {
      process.env.REVIEW_VAULT_ROOT = previousReviewRoot;
    }
    rmSync(tempRoot, { recursive: true, force: true });
  }
});
```

