- [ ] **Step 3: Add review-root helpers**

In `scripts/lib/config.mjs`, after `toWorldMachineRelative`, add:

```js
/** Get the active human review vault root path. Defaults to World_Machine. */
export function getReviewVaultRoot() {
  const configured = process.env.REVIEW_VAULT_ROOT?.trim();
  if (configured && resolve(configured) !== ENGINE_ROOT) {
    return resolve(configured);
  }
  return getWorldMachineRoot();
}

/** Resolve a path under the active human review vault root. */
export function resolveReviewPath(...parts) {
  return resolve(getReviewVaultRoot(), ...parts);
}

/** Convert an absolute path to a review-vault-relative display path. */
export function toReviewRelative(absPath) {
  return relative(getReviewVaultRoot(), absPath).split(sep).join('/');
}
```

