- [ ] **Step 1: Create a failing unit test**

Create `scripts/tests/source-gap-register.test.mjs`:

```js
import assert from 'node:assert/strict';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { run } from '../system/source-gap-register.mjs';

async function runTest(name, fn) {
  try {
    await fn();
    console.log(`ok - ${name}`);
  } catch (error) {
    console.error(`not ok - ${name}`);
    console.error(error);
    process.exitCode = 1;
  }
}

await runTest('source gap register reads and writes the review vault root', async () => {
  const previousWorldRoot = process.env.WORLD_MACHINE_ROOT;
  const previousResearchRoot = process.env.RESEARCH_VAULT_ROOT;
  const worldRoot = mkdtempSync(join(tmpdir(), 'world-machine-review-'));
  const researchRoot = mkdtempSync(join(tmpdir(), 'archived-research-spine-'));

  try {
    process.env.WORLD_MACHINE_ROOT = worldRoot;
    process.env.RESEARCH_VAULT_ROOT = researchRoot;

    const summaryDir = join(worldRoot, 'Reports', 'System', 'run_summaries');
    mkdirSync(summaryDir, { recursive: true });
    writeFileSync(join(summaryDir, '2026-05-15_09-30.md'), [
      '| Puller | Status |',
      '|---|---|',
      '| gdelt | FAILED |',
    ].join('\n'), 'utf-8');

    await run({});

    const outPath = join(worldRoot, 'Reports', 'Source Gap Register.md');
    assert.equal(existsSync(outPath), true);
    assert.match(readFileSync(outPath, 'utf-8'), /gdelt/);
    assert.equal(existsSync(join(researchRoot, '99_System', 'Source_Gap_Register.md')), false);
  } finally {
    restoreEnv('WORLD_MACHINE_ROOT', previousWorldRoot);
    restoreEnv('RESEARCH_VAULT_ROOT', previousResearchRoot);
    rmSync(worldRoot, { recursive: true, force: true });
    rmSync(researchRoot, { recursive: true, force: true });
  }
});

function restoreEnv(name, value) {
  if (value === undefined) {
    delete process.env[name];
  } else {
    process.env[name] = value;
  }
}
```

