import { pull } from '../pullers/research-spine-flow.mjs';

await runTest('review vault defaults to World_Machine and resolves review paths', async () => {
  const previousWorldRoot = process.env.WORLD_MACHINE_ROOT;
  const previousReviewRoot = process.env.REVIEW_VAULT_ROOT;
  const tempRoot = mkdtempSync(join(tmpdir(), 'world-machine-review-'));

  try {
    process.env.WORLD_MACHINE_ROOT = tempRoot;
    delete process.env.REVIEW_VAULT_ROOT;

    assert.equal(getReviewVaultRoot(), tempRoot);
